// SkadiAsset.swift — baked Skadi (the Corrupting Heart) build-chibi frames.
//
// Sprite strips (200×240 per frame) rendered OFFLINE from arkdock's Spine data
// via pixi-spine in headless Chrome, then quantized and base64-embedded so the
// bare binary needs no resource bundle — same convention as BongoCatAsset.
//   Relax = idle breathing;  Move = walk cycle (played while an agent works).

import CoreGraphics
import Foundation
import ImageIO

enum SkadiAsset {
    static let frameWidth = 200
    static let frameHeight = 240
    nonisolated(unsafe) static let relaxFrames: [CGImage] = slice(decode(relaxB64))
    nonisolated(unsafe) static let moveFrames: [CGImage] = slice(decode(moveB64))

    private static func decode(_ b64: String) -> CGImage? {
        guard let data = Data(base64Encoded: b64),
              let src = CGImageSourceCreateWithData(data as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }

    private static func slice(_ sheet: CGImage?) -> [CGImage] {
        guard let sheet = sheet, sheet.width >= frameWidth else { return [] }
        let n = sheet.width / frameWidth
        var out: [CGImage] = []
        for i in 0..<n {
            if let f = sheet.cropping(to: CGRect(x: i * frameWidth, y: 0,
                                                 width: frameWidth, height: sheet.height)) {
                out.append(f)
            }
        }
        return out
    }

